// mapping-loader (spec M7 §5, §4.4) — init a ogni deploy/avvio (inject once).
// Legge /data/tag-mapping.js, artefatto generato dalle costanti del simulatore.
// I node_id non sono presenti in questo flow: sono risolti a runtime dal mapping.
// Se il file manca, è invalido o contiene duplicati, l'acquisizione resta no-op.
var MAPPING_FILE = '/data/tag-mapping.js';
var mapping = null;
try {
    var src = fs.readFileSync(MAPPING_FILE, 'utf8');
    var marker = src.lastIndexOf('module.exports');
    var start = src.indexOf('[', marker >= 0 ? marker : 0);
    var end = src.lastIndexOf(']');
    if (start < 0 || end <= start) {
        throw new Error('formato inatteso: nessun array JSON in ' + MAPPING_FILE);
    }
    var arrSrc = src.slice(start, end + 1).replace(/,\\s*\\]\\s*$/, ']');
    mapping = JSON.parse(arrSrc);
} catch (err) {
    node.error('[mapping-loader] file non leggibile o mapping non valido: ' + err.message +
        ' — acquisizione DISATTIVATA (no-op). Rigenerare il mapping con: ' +
        'python edge/scripts/build_tag_mapping.py --generate');
    flow.set('m7.tagMapping', null);
    flow.set('m7.nodeIndex', null);
    flow.set('m7.valveGroups', null);
    flow.set('m7.ready', false);
    node.status({ fill: 'red', shape: 'ring', text: 'mapping: NON caricato' });
    return null;
}
if (!Array.isArray(mapping) || mapping.length === 0) {
    node.error('[mapping-loader] mapping vuoto o non-array — no-op');
    flow.set('m7.ready', false);
    return null;
}
var bad = mapping.filter(function (e) {
    return !e || !e.logical_name || !e.node_id;
});
if (bad.length > 0) {
    node.error('[mapping-loader] ' + bad.length +
        ' voce/i senza logical_name/node_id — no-op');
    flow.set('m7.ready', false);
    return null;
}
var index = {};
var duplicateNodeIds = [];
mapping.forEach(function (e) {
    if (index[e.node_id] && index[e.node_id] !== e.logical_name) {
        duplicateNodeIds.push(e.node_id);
    }
    index[e.node_id] = e.logical_name;
});
if (duplicateNodeIds.length > 0) {
    node.error('[mapping-loader] node_id duplicati: ' +
        duplicateNodeIds.join(', ') + ' — no-op');
    flow.set('m7.ready', false);
    return null;
}

// Raggruppa i tag ValveNN e richiede un LastCycleId per ogni gruppo.
// Il trigger di una valvola è il suo LastCycleId; nessun tag machine.*
// identifica quale valvola ha chiuso il ciclo.
var valveGroups = {};
mapping.forEach(function (e) {
    var match = /^valve(\d{2})\.(.+)$/.exec(e.logical_name);
    if (!match) { return; }
    var group = 'valve' + match[1];
    if (!valveGroups[group]) { valveGroups[group] = {}; }
    valveGroups[group][match[2]] = e;
});
var valveNames = Object.keys(valveGroups).sort();
var missingTriggers = valveNames.filter(function (group) {
    return !valveGroups[group].last_cycle_id;
});
if (valveNames.length === 0 || missingTriggers.length > 0) {
    node.error('[mapping-loader] mapping senza trigger LastCycleId per: ' +
        (missingTriggers.length ? missingTriggers.join(', ') : 'nessuna valvola') +
        ' — no-op');
    flow.set('m7.ready', false);
    return null;
}

flow.set('m7.tagMapping', mapping);
flow.set('m7.nodeIndex', index);
flow.set('m7.valveGroups', valveGroups);
flow.set('m7.ready', true);
flow.set('m7.tagStore', {});
flow.set('m7.watermarks', {});
node.log('[mapping-loader] mapping caricato: ' + mapping.length + ' voci (' +
    mapping.filter(function (e) { return /^machine\./.test(e.logical_name); }).length +
    ' machine + ' + valveNames.length + ' valve groups; ' +
    valveNames.length + ' LastCycleId triggers) da ' + MAPPING_FILE);
node.status({ fill: 'green', shape: 'dot',
    text: 'mapping: ' + mapping.length + ' voci / ' + valveNames.length + ' valve' });
return msg;

// subscription-setup (spec M7 §5, §4.3) — costruisce la subscription a runtime.
// Tutti i node_id arrivano dal mapping-loader. Ogni ValveNN.LastCycleId è un
// trigger indipendente: il tag condiviso machine.* non identifica una valvola.
// Se il mapping non è pronto o manca un trigger per un gruppo, no-op.
var mapping = flow.get('m7.tagMapping');
var valveGroups = flow.get('m7.valveGroups');
if (!Array.isArray(mapping) || !valveGroups) {
    node.warn('[subscribe] mapping non disponibile nel context — subscription NON creata');
    node.status({ fill: 'red', shape: 'ring', text: 'subscribe: SKIP (no mapping)' });
    return null;
}
var valveNames = Object.keys(valveGroups).sort();
var triggerCount = 0;
var subscriptions = [];
mapping.forEach(function (e) {
    if (e && e.node_id) {
        subscriptions.push({ nodeId: e.node_id });
    }
    if (e && /^valve\d{2}\.last_cycle_id$/.test(e.logical_name)) {
        triggerCount += 1;
    }
});
if (valveNames.length === 0 || triggerCount !== valveNames.length) {
    node.error('[subscribe] trigger LastCycleId incompleti: ' + triggerCount +
        ' per ' + valveNames.length + ' valvole — subscription NON creata');
    return null;
}
flow.set('m7.valveTriggerCount', triggerCount);
node.log('[subscribe] subscription: ' + subscriptions.length + ' item dal mapping; ' +
    triggerCount + ' trigger LastCycleId per ' + valveNames.length + ' valvole');
node.status({ fill: 'blue', shape: 'dot',
    text: 'subscribe: ' + subscriptions.length + ' item / ' + triggerCount + ' trigger' });
var out = [];
out.push({ topic: 'multiple', payload: subscriptions });
return [out];

// watermark-acquisition (spec M7 §4.3) — un watermark indipendente per valvola.
// msg.topic è il node_id del mapping; il trigger utile è sempre
// valveNN.last_cycle_id. Le notifiche degli altri tag aggiornano solo lo store.
var mapping = flow.get('m7.tagMapping');
var index = flow.get('m7.nodeIndex');
if (!Array.isArray(mapping) || !index) {
    node.warn('[watermark] mapping assente nel context — skip');
    return null;
}
var logical = index[msg.topic];
if (!logical) {
    node.warn('[watermark] nodeId non presente nel mapping: ' + msg.topic);
    return null;
}

var dv = msg.payload || {};
var sc = dv.statusCode;
var good = true;
if (sc !== undefined && sc !== null) {
    good = (typeof sc.value === 'number') ? (sc.value === 0) : true;
}
var raw = null;
if (dv.value !== undefined && dv.value !== null) {
    raw = (typeof dv.value === 'object' && 'value' in dv.value) ? dv.value.value : dv.value;
}
var val = null;
if (good) {
    try {
        if (Array.isArray(raw) && raw.length === 2) {
            val = raw[0] * 4294967296 + raw[1];
        } else {
            val = (typeof raw === 'bigint') ? Number(raw) : raw;
        }
    } catch (e) {
        val = null;
    }
}
var serverMs = null;
var st = dv.serverTimestamp;
if (st instanceof Date) { serverMs = st.getTime(); }
else if (typeof st === 'number') { serverMs = st; }
else if (st) { try { serverMs = new Date(st).getTime(); } catch (e) { serverMs = null; } }

var store = flow.get('m7.tagStore') || {};
store[logical] = { v: val, ts: serverMs, good: good };
flow.set('m7.tagStore', store);

var triggerMatch = /^valve(\d{2})\.last_cycle_id$/.exec(logical);
if (!triggerMatch || val === null || val === undefined) {
    return null;
}
var valveGroup = 'valve' + triggerMatch[1];
var cycleId = Number(val);
if (!isFinite(cycleId)) {
    node.warn('[watermark] LastCycleId non numerico per ' + valveGroup + ' — skip');
    return null;
}

var watermarks = flow.get('m7.watermarks') || {};
var state = watermarks[valveGroup];
if (!state) {
    watermarks[valveGroup] = { watermark: cycleId, initCycleId: cycleId };
    flow.set('m7.watermarks', watermarks);
    node.log('[watermark] init ' + valveGroup + ': LastCycleId = ' + cycleId +
        ' (nessun backfill)');
    node.status({ fill: 'green', shape: 'dot',
        text: valveGroup + ' init: ' + cycleId });
    return null;
}
var wm = Number(state.watermark);
if (cycleId < wm) {
    watermarks[valveGroup] = { watermark: cycleId, initCycleId: state.initCycleId,
        epochReset: true };
    flow.set('m7.watermarks', watermarks);
    node.warn('[watermark] epoch reset ' + valveGroup + ': LastCycleId ' + cycleId +
        ' < watermark ' + wm + ' (server riavviato)');
    node.status({ fill: 'yellow', shape: 'ring',
        text: valveGroup + ' reset: ' + cycleId });
    return null;
}
if (cycleId === wm) {
    return null;
}

var gaps = cycleId - wm - 1;
if (gaps > 0) {
    node.warn('[watermark] GAP ' + valveGroup + ': ' + gaps +
        ' ciclo/i tra watermark ' + wm + ' e LastCycleId ' + cycleId +
        ' non più leggibili — pubblicato l’ultimo blocco');
}
var block = {};
var sourceTs = null;
mapping.forEach(function (e) {
    if (!e.logical_name || e.logical_name.indexOf(valveGroup + '.') !== 0) {
        return;
    }
    var saved = store[e.logical_name];
    block[e.logical_name] = (saved && saved.good) ? saved.v : null;
    if (saved && saved.ts !== null && saved.ts !== undefined &&
        (sourceTs === null || saved.ts > sourceTs)) {
        sourceTs = saved.ts;
    }
});
watermarks[valveGroup] = { watermark: cycleId, initCycleId: state.initCycleId };
flow.set('m7.watermarks', watermarks);
node.status({ fill: 'green', shape: 'dot',
    text: valveGroup + ' cycle ' + cycleId });
return {
    payload: {
        cycleCounter: cycleId,
        cycleId: cycleId,
        valveId: parseInt(triggerMatch[1], 10),
        valveGroup: valveGroup,
        block: block,
        sourceTs: sourceTs
    }
};

// builder-envelope (spec M7 §4.2, contratto M9): costruisce l'envelope JSON v1.2.
// Nessuna logica di business: normalizzazione e impacchettamento.
// Ingresso: { payload: { cycleId, valveId, valveGroup, block, sourceTs } }.
var p = msg.payload || {};
var block = p.block || {};
var sourceTsMs = p.sourceTs;

var eventId = null;
try { eventId = crypto.randomUUID(); } catch (e) { eventId = null; }
if (!eventId) {
    eventId = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
        var r = Math.random() * 16 | 0;
        var v = (c === 'x') ? r : ((r & 0x3) | 0x8);
        return v.toString(16);
    });
}
var eventTs = new Date().toISOString();
var sourceTs = eventTs;
if (sourceTsMs !== null && sourceTsMs !== undefined) {
    try {
        var d = (sourceTsMs instanceof Date) ? sourceTsMs : new Date(sourceTsMs);
        if (!isNaN(d.getTime())) { sourceTs = d.toISOString(); }
    } catch (e) { /* fallback: event_ts */ }
}

// Il gruppo arriva dal trigger LastCycleId. Non si sceglie una valvola fissa.
var valveGroup = (typeof p.valveGroup === 'string' &&
    /^valve\d{2}$/.test(p.valveGroup)) ? p.valveGroup : null;
if (!valveGroup) {
    var blockKeys = Object.keys(block);
    for (var i = 0; i < blockKeys.length; i += 1) {
        if (/^valve\d{2}\./.test(blockKeys[i])) {
            valveGroup = blockKeys[i].slice(0, 6);
            break;
        }
    }
}
if (!valveGroup) {
    node.warn('[builder] valveGroup assente — envelope non emesso');
    return null;
}
var valveMatch = /^valve(\d{2})$/.exec(valveGroup);
var valveId = valveMatch ? parseInt(valveMatch[1], 10) : Number(p.valveId);
if (!isFinite(valveId)) {
    node.warn('[builder] valveId non valido per ' + valveGroup);
    return null;
}
var prefix = valveGroup;

// data.* — i 15 campi del contratto envelope v1.2, senza prefisso valveNN.
var DATA_KEYS = ['filling_time_ms', 'tail_time_ms', 'tail_pulse', 'pulse_count',
    'target', 'delta_pulse', 'filling_step_out', 'filling_ok',
    'fill_quality_ok', 'sequence_ok', 'sample_valid', 'diagnostic_status',
    'close_reason', 'position_limit', 'filling_overtime'];
var data = {};
var complete = true;
DATA_KEYS.forEach(function (k) {
    var v = block[prefix + '.' + k];
    if (v === undefined || v === null) {
        data[k] = null;
        complete = false;
    } else {
        try { data[k] = (typeof v === 'bigint') ? Number(v) : v; }
        catch (e) { data[k] = null; complete = false; }
    }
});

var cycleId = block[prefix + '.last_cycle_id'];
if (cycleId === undefined || cycleId === null) {
    cycleId = p.cycleId;
}
if (cycleId === undefined || cycleId === null) {
    node.error('[builder] LastCycleId assente per ' + valveGroup +
        ' — envelope non emesso');
    return null;
}
try {
    if (Array.isArray(cycleId) && cycleId.length === 2) {
        cycleId = cycleId[0] * 4294967296 + cycleId[1];
    } else {
        cycleId = Number(cycleId);
    }
} catch (e) {
    node.error('[builder] LastCycleId non convertibile per ' + valveGroup +
        ' — envelope non emesso');
    return null;
}
if (!isFinite(cycleId)) {
    node.error('[builder] LastCycleId non numerico per ' + valveGroup +
        ' — envelope non emesso');
    return null;
}

var env = {
    schema_version: '1.2',
    event_id: eventId,
    event_type: 'valve_cycle',
    event_ts: eventTs,
    source_ts: sourceTs,
    machine_id: 'filler01',
    cycle_id: cycleId,
    valve_id: valveId,
    data: data,
    quality: { valid: complete, completeness: complete ? 'complete' : 'partial' }
};
node.status({ fill: 'green', shape: 'dot', text: valveGroup + ' env ' + env.cycle_id });
msg.payload = env;
return msg;
